export type Status = 'todo' | 'in_progress' | 'done' | 'blocked';
export interface Thread { id: string; guildId: string; channelId: string; project: string; title: string; authorId: string }
export interface Event { id: string; thread: Thread; message?: { id: string; authorId: string; author: string; content: string; timestamp: string } }
export function projectKey(name: string): string | undefined {
  const match = /^proj-([a-z][a-z0-9]*)$/i.exec(name);
  return match?.[1]?.toUpperCase();
}
export function statusOf(content: string): Status | undefined {
  const matches = [...content.matchAll(/\bstatus:\s*(todo|in_progress|done|blocked)\b/gi)];
